import base64, ctypes as c, io, os, shutil, subprocess, time
from pathlib import Path
from PIL import Image
from pywinauto import Desktop

DEV=Path(r"C:\dev\flyExplorer")
BASE=Path(r"C:\dev\flyExplorer-known-folder-baseline")
PROFILE=Path(os.environ["USERPROFILE"])
LABELS={
 "Desktop":("바탕 화면","Desktop"),
 "Documents":("문서","Documents"),
 "Downloads":("다운로드","Downloads"),
 "Pictures":("사진","Pictures"),
 "Music":("음악","Music"),
 "Videos":("동영상","Videos"),
}
def until(fn,why,timeout=30):
 end=time.monotonic()+timeout
 last=None
 while time.monotonic()<end:
  try:
   v=fn()
   if v:return v
  except Exception as e:last=e
  time.sleep(.25)
 raise AssertionError(f"{why}; last={last!r}")
def enc(img):
 img=img.convert("RGB")
 img.thumbnail((972,720))
 b=io.BytesIO();img.save(b,format="JPEG",quality=84,optimize=True)
 return base64.b64encode(b.getvalue()).decode("ascii")
def collect(pane):
 found={}
 for item in pane.descendants():
  try:
   if item.element_info.control_type!="ListItem":continue
   name=(item.element_info.name or item.window_text() or "")
   for key,labels in LABELS.items():
    if any(f"  {label}   |" in name for label in labels):
     found.setdefault(key,(item,name));break
  except Exception:pass
 return found
def run_one(exe,tag,expect_known):
 owned=DEV/"logs"/f"known-folder-visual-{tag.lower()}"
 if owned.exists():shutil.rmtree(owned)
 (owned/"localappdata"/"flyExplorer").mkdir(parents=True)
 (owned/"appdata").mkdir();(owned/"temp").mkdir()
 (owned/"localappdata"/"flyExplorer"/"ui-preferences-v1.txt").write_text(
  "schema=2\r\nlanguage=ko-KR\r\ntheme=dark\r\nview=large-icons\r\n",
  encoding="ascii",newline="")
 env=os.environ.copy()
 env["LOCALAPPDATA"]=str(owned/"localappdata");env["APPDATA"]=str(owned/"appdata")
 env["TEMP"]=env["TMP"]=str(owned/"temp")
 p=subprocess.Popen([str(exe),str(PROFILE)],cwd=exe.parent,env=env)
 spec=None
 try:
  def get():
   ws=[w for w in Desktop(backend="uia").windows(process=p.pid) if "flyExplorer" in w.window_text()]
   return Desktop(backend="uia").window(handle=ws[0].handle) if len(ws)==1 else None
  spec=until(get,f"{tag} window missing")
  wrap=spec.wrapper_object()
  try:wrap.move_window(x=40,y=40,width=972,height=720,repaint=True)
  except Exception:pass
  pane=spec.child_window(auto_id="LeftFiles").wrapper_object()
  found=until(lambda:(lambda x:x if len(x)==6 else None)(collect(pane)),
              f"{tag} Known Folder rows incomplete",30)
  # Bring the six-folder cluster into the viewport.
  try:found["Downloads"][0].scroll_into_view()
  except Exception:pass
  time.sleep(.8)
  print(tag+"_COUNT",len(found),flush=True)
  for key in LABELS:
   item,name=found[key]
   images=[]
   for x in item.descendants():
    try:
     if x.element_info.control_type=="Image":
      images.append(x.element_info.name or "")
    except Exception:pass
   known=sum(x=="Windows Known Folder artwork" for x in images)
   generic=sum(x=="Windows Shell folder icon" for x in images)
   r=item.rectangle()
   print(tag+"_ROW",key,repr(name),r.left,r.top,r.width(),r.height(),
         "KNOWN",known,"GENERIC",generic,"IMAGES",repr(images),flush=True)
   if expect_known and known!=1:raise AssertionError(f"{tag} {key}: known={known}")
   if not expect_known and generic!=1:raise AssertionError(f"{tag} {key}: generic={generic}")
  print(tag+"_SCREENSHOT_BEGIN",flush=True)
  print(enc(wrap.capture_as_image()),flush=True)
  print(tag+"_SCREENSHOT_END",flush=True)
 finally:
  if p.poll() is None:
   try:
    c.windll.user32.PostMessageW(spec.wrapper_object().handle,0x10,0,0);p.wait(timeout=10)
   except Exception:
    p.terminate();p.wait(timeout=8)
 print(tag+"_EXIT",p.returncode,flush=True)
 if p.returncode!=0:raise AssertionError(f"{tag} process exit {p.returncode}")

run_one(BASE/"out"/"winui"/"Release"/"flyExplorer.exe","BEFORE",False)
run_one(DEV/"out"/"winui"/"Release"/"flyExplorer.exe","AFTER",True)

